// 모험가의 손 등불 (길 잃은 모험가의 망령 A): 넋불이 든 작은 쇠 등불
PXU_WPN.ghostlamp = (F, d) => { const [hx, hy] = pxsMHand(F), [dx, dy] = pxsDir(F.a || 0), px = -dy, py = dx, out = [], k = (d && d.ms) || 1, L = 3.0 * k, o = L - 3.0;
  const at = (t, s, ch) => out.push([hx + 0.5 + dx * t + px * s, hy + 0.5 + dy * t + py * s, ch]);
  for (let t = -0.5; t <= L; t += 0.5) at(t, 0, t < -0.5 + 0.6 ? 'g' : 'g');
  for (const [t, s, ch] of [[6.5,-0.5,'G'],[6.5,0.5,'G'],[5.5,-1.5,'G'],[5.5,-0.5,'L'],[5.5,0.5,'L'],[5.5,1.5,'G'],[4.5,-1.5,'G'],[4.5,-0.5,'l'],[4.5,0.5,'l'],[4.5,1.5,'G'],[3.5,-0.5,'G'],[3.5,0.5,'G']]) for (const e of [-0.25, 0.25]) for (const f of [-0.25, 0.25]) at(t + o + e, s + f, ch);
  return out; };
PXU_FXW.ghostlamp = 'staff';
// 부러진 칼 (길 잃은 모험가의 망령 B): 반쯤 부러진 날
PXU_WPN.brokensword = (F, d) => { const [hx, hy] = pxsMHand(F), [dx, dy] = pxsDir(F.a || 0), px = -dy, py = dx, out = [], k = (d && d.ms) || 1, L = 3.5 * k, o = L - 3.5;
  const at = (t, s, ch) => out.push([hx + 0.5 + dx * t + px * s, hy + 0.5 + dy * t + py * s, ch]);
  for (let t = -1.5; t <= L; t += 0.5) at(t, 0, t < -1.5 + 0.6 ? 'g' : 'N');
  for (const [t, s, ch] of [[7.0,-0.5,'N'],[6.0,-0.5,'N'],[6.0,0.5,'N'],[5.0,0.5,'N'],[4.0,0.5,'N']]) for (const e of [-0.25, 0.25]) for (const f of [-0.25, 0.25]) at(t + o + e, s + f, ch);
  return out; };
PXU_FXW.brokensword = 'sword';
